#!/usr/bin/env bash
# Day 3 (D12) - build docker/.env.compose from Azure Key Vault.
# The secrets are generated by Terraform (terraform/lab) and stored in Key Vault;
# this script pulls them at deploy time, so no secret is typed into a file by hand
# or committed to git. Your Azure login decides access (Key Vault access policy).
#
# Usage: scripts/env-from-keyvault.sh [key-vault-name]
#        (default: the key_vault_name output of terraform/lab)
set -euo pipefail

DP="$(cd "$(dirname "$0")/.." && pwd)"
KV="${1:-$(terraform -chdir="$DP/terraform/lab" output -raw key_vault_name)}"
OUT="$DP/docker/.env.compose"

get() { az keyvault secret show --vault-name "$KV" --name "$1" --query value -o tsv; }

echo "Reading configuration from Key Vault: $KV"
POSTGRES_USER=$(get postgres-user)
POSTGRES_PASSWORD=$(get postgres-password)
POSTGRES_DB=$(get postgres-db)
JWT_SECRET=$(get jwt-secret)

umask 077                       # file is created readable by you only
TMP="$(mktemp "$OUT.XXXX")"
cat > "$TMP" <<ENV
# Generated from Key Vault $KV on $(date -u +%FT%TZ) - do not edit or commit.
POSTGRES_USER=$POSTGRES_USER
POSTGRES_PASSWORD=$POSTGRES_PASSWORD
POSTGRES_DB=$POSTGRES_DB
JWT_SECRET=$JWT_SECRET
ENV
mv "$TMP" "$OUT"
echo "Wrote $OUT (mode $(stat -c %a "$OUT" 2>/dev/null || stat -f %Lp "$OUT")). Values are not printed."
echo "Next: make down V=1 && make up && make seed   (new DB password needs a fresh volume)"
